// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(address caller, address recipient) public {
        vm.assume(caller != address(0));
        vm.assume(recipient != address(0));

        uint256 seedAmount = bound(uint256(1), 1, 1 ether);
        vm.deal(address(this), seedAmount);
        (bool sent, ) = address(c).call{value: seedAmount}("");
        require(sent);

        bool ok;
        vm.prank(caller);
        try c.withdrawAll(recipient) {
            ok = true;
        } catch {
            ok = false;
        }

        bool ownerIsCaller = (caller == c.owner());
        assertTrue(ok == ownerIsCaller);
    }
}
